CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,discord_id TEXT UNIQUE NOT NULL,discord_name TEXT NOT NULL,avatar TEXT,character_name TEXT COLLATE NOCASE UNIQUE,role TEXT NOT NULL DEFAULT 'member',status TEXT NOT NULL DEFAULT 'active',onboarding_completed INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT NOT NULL,expires_at TEXT NOT NULL,discord_role_id TEXT,active INTEGER NOT NULL DEFAULT 1,deleted_at TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS renewals(id INTEGER PRIMARY KEY AUTOINCREMENT,asset_id INTEGER NOT NULL,old_expires_at TEXT,new_expires_at TEXT NOT NULL,cost INTEGER NOT NULL DEFAULT 0,user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS alert_state(asset_id INTEGER PRIMARY KEY,last_threshold INTEGER,discord_message_id TEXT,last_sent_at TEXT,FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS asset_alert_settings(asset_id INTEGER PRIMARY KEY,reminder_hours TEXT NOT NULL DEFAULT '72,24,12,6,1',webhook_slot TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS money_balances(owner TEXT PRIMARY KEY,clean INTEGER NOT NULL DEFAULT 0,dirty INTEGER NOT NULL DEFAULT 0,updated_by INTEGER,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS money_log(id INTEGER PRIMARY KEY AUTOINCREMENT,owner TEXT NOT NULL,old_clean INTEGER,old_dirty INTEGER,new_clean INTEGER,new_dirty INTEGER,user_id INTEGER,undone INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS calendar_events(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT,created_by INTEGER,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS calendar_event_settings(event_id INTEGER PRIMARY KEY,notification_category TEXT,reminder_hours TEXT NOT NULL DEFAULT '72,24,12,6,1',discord_role_id TEXT,enabled INTEGER NOT NULL DEFAULT 0,last_threshold INTEGER,discord_message_id TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES calendar_events(id));
CREATE TABLE IF NOT EXISTS players(id INTEGER PRIMARY KEY AUTOINCREMENT,cid TEXT UNIQUE NOT NULL,name TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY AUTOINCREMENT,contract_no TEXT UNIQUE NOT NULL,player_id INTEGER NOT NULL,vehicle_name TEXT NOT NULL,registration TEXT NOT NULL,purchase_date TEXT NOT NULL,price INTEGER NOT NULL,payment_method TEXT NOT NULL,extra_terms TEXT,seller_user_id INTEGER,document_key TEXT,deleted_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(player_id) REFERENCES players(id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_reads(user_id INTEGER NOT NULL,notification_id INTEGER NOT NULL,read_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,notification_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(notification_id) REFERENCES notifications(id));
CREATE TABLE IF NOT EXISTS push_subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,endpoint TEXT UNIQUE NOT NULL,p256dh TEXT NOT NULL,auth TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_log(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,payload TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
